using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using TMPro;
public static class SetupMudRecovery {
static void Ref(SerializedObject so,string field,UnityEngine.Object target)=>so.FindProperty(field).objectReferenceValue=target;
static TMP_Text Label(Transform parent,string name,string text,float size,float y,float height,Color color,TMP_FontAsset font){var g=new GameObject(name,typeof(RectTransform),typeof(CanvasRenderer),typeof(TextMeshProUGUI));g.layer=5;g.transform.SetParent(parent,false);var r=(RectTransform)g.transform;r.anchorMin=r.anchorMax=new Vector2(.5f,1);r.pivot=new Vector2(.5f,1);r.anchoredPosition=new Vector2(0,y);r.sizeDelta=new Vector2(468,height);var label=g.GetComponent<TextMeshProUGUI>();label.font=font;label.fontSize=size;label.text=text;label.alignment=TextAlignmentOptions.Center;label.color=color;label.raycastTarget=false;label.textWrappingMode=TextWrappingModes.NoWrap;return label;}
public static string Main(){var scene=SceneManager.GetActiveScene();if(EditorApplication.isPlaying||scene.isDirty||scene.path!="Assets/Scenes/TestTrackScene.unity")throw new Exception("Clean TestTrackScene in Edit mode required");var controls=UnityEngine.Object.FindAnyObjectByType<TestDriveTouchControls>();var controlSo=new SerializedObject(controls);var safe=(RectTransform)controlSo.FindProperty("hudSafeArea").objectReferenceValue;if(safe==null||safe.Find("MudRecoveryPrompt"))throw new Exception("Expected existing HUD safe area without recovery prompt");var reset=(RectTransform)controlSo.FindProperty("resetButton").objectReferenceValue;var trial=GameObject.Find("Offroad Course/Mud and Water Trial").transform;var bed=trial.Find("Deep mud bed").GetComponent<TestDriveSurface>();if(reset==null||bed==null)throw new Exception("Existing reset/mud bed missing");
var recovery=new GameObject("MudDryRecoveryPoint").transform;recovery.SetParent(trial,false);float u=.49f;recovery.position=new Vector3(155+80*u,1.02f,-30-40*Mathf.Pow(Mathf.Sin(Mathf.PI*u),2));recovery.rotation=Quaternion.LookRotation(new Vector3(80,0,-40*Mathf.PI*Mathf.Sin(2*Mathf.PI*u)));var surfaceSo=new SerializedObject(bed);surfaceSo.FindProperty("mudBogResistance").floatValue=4.5f;Ref(surfaceSo,"recoveryPoint",recovery);surfaceSo.ApplyModifiedPropertiesWithoutUndo();
var panel=new GameObject("MudRecoveryPrompt",typeof(RectTransform),typeof(CanvasRenderer),typeof(UnityEngine.UI.Image),typeof(CanvasGroup),typeof(TestDriveRecoveryPrompt));panel.layer=5;panel.transform.SetParent(safe,false);var rect=(RectTransform)panel.transform;rect.anchorMin=rect.anchorMax=new Vector2(.5f,0);rect.pivot=new Vector2(.5f,0);rect.anchoredPosition=new Vector2(0,236);rect.sizeDelta=new Vector2(500,184);var image=panel.GetComponent<UnityEngine.UI.Image>();image.color=new Color(.025f,.05f,.06f,.96f);image.raycastTarget=false;var border=panel.AddComponent<UnityEngine.UI.Outline>();border.effectColor=new Color(.98f,.77f,.25f,.7f);border.effectDistance=new Vector2(2,-2);var group=panel.GetComponent<CanvasGroup>();group.alpha=0;group.interactable=group.blocksRaycasts=false;var font=AssetDatabase.LoadAssetAtPath<TMP_FontAsset>("Assets/Fonts/Nunito/Nunito-Bold SDF.asset");Label(panel.transform,"Heading","BOGGED DOWN",38,-10,42,new Color(.98f,.77f,.25f),font);var message=Label(panel.transform,"Message","Try reversing to escape.\nOr tap RECOVER for dry ground.",30,-56,78,new Color(.96f,.98f,1),font);Label(panel.transform,"VehicleAdvice","Off-road vehicles cope better.",24,-144,30,new Color(.73f,.81f,.82f),font);
var prompt=panel.GetComponent<TestDriveRecoveryPrompt>();var so=new SerializedObject(prompt);Ref(so,"panel",group);Ref(so,"message",message);Ref(so,"resetFace",reset.GetComponent<UnityEngine.UI.Image>());Ref(so,"resetLabel",reset.GetComponentInChildren<TMP_Text>());Ref(so,"resetOutline",reset.GetComponent<UnityEngine.UI.Outline>());so.ApplyModifiedPropertiesWithoutUndo();Ref(controlSo,"recoveryPrompt",prompt);Ref(controlSo,"recoveryPanel",rect);controlSo.ApplyModifiedPropertiesWithoutUndo();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();return "Added depth-dependent bogging, nearby dry recovery point, non-blocking safe-area help and highlighted RECOVER state; original reset click binding retained.";}}
